package dev.bre.decision.log;

import dev.bre.decision.api.DecisionApi.DecisionResponse;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;

/**
 * A durable decision record (LLD §5.3).
 *
 * <p>Holds the resolved {@code asOf}, the engine version and the facts the decision was made from,
 * which together are what make "replay this decision from March" exact (D7, D8): the explanation is
 * regenerated by re-evaluating the stored facts against the stored bundle, rather than by storing a
 * trace per rule — roughly ten times less storage for the same answer.
 *
 * @param decisionId the identifier. A UUIDv7, so the hot store can derive its partition date from
 *     it (ADR-008, §5.3).
 * @param tenantId the tenant
 * @param requestId the caller's idempotency key
 * @param applicationRef the application this decision is about, for the by-application index
 * @param receivedAt when the request arrived
 * @param recordedAt when the decision completed and was written
 * @param latencyMicros how long the decision took, in microseconds
 * @param timeZone the tenant time zone that resolved {@code asOf} (00 §3.7a)
 * @param fuelUsed how much evaluation fuel the decision spent (§3.10)
 * @param policyCode the policy's code, once the registry supplies one (M3)
 * @param policyVersion the policy version
 * @param bundleHash the content hash of the bundle that decided it — the anchor a replay pins to
 * @param factSchema the fact schema the snapshot conforms to
 * @param response the decision as returned to the caller
 * @param factsJson the fact snapshot, as submitted
 */
public record DecisionRecord(
    String decisionId,
    String tenantId,
    String requestId,
    Optional<String> applicationRef,
    Instant receivedAt,
    Instant recordedAt,
    long latencyMicros,
    String timeZone,
    long fuelUsed,
    Optional<String> policyCode,
    Optional<Integer> policyVersion,
    Optional<String> bundleHash,
    String factSchema,
    DecisionResponse response,
    String factsJson) {

  /** Creates a record. */
  public DecisionRecord {
    Objects.requireNonNull(decisionId, "decisionId");
    Objects.requireNonNull(tenantId, "tenantId");
    Objects.requireNonNull(requestId, "requestId");
  }

  /**
   * Reconstructs the part of a record a read returns.
   *
   * <p>A read deliberately does <b>not</b> return the facts: with {@code
   * bre.decision-log.store-facts} off they were never stored, and when they were, handing them back
   * on an ordinary lookup would spread personal data further than the lookup needs. They are
   * fetched separately, by the replay path, through {@link DecisionLog#facts}.
   *
   * <p><b>The bundle hash is not optional in practice and is a parameter for that reason.</b> An
   * earlier version of this method defaulted it to empty, on the stated plan that the replay path
   * would fetch it itself when that path existed. The path was built and did not — it reads the
   * record — so every explanation against PostgreSQL failed with "has no bundleHash", for every
   * decision, from the day the endpoint shipped. Nothing caught it: the in-memory log returns whole
   * records so the tests passed, and the one devstack check asserted on a substring that the HTTP
   * 500 error body also contained. Making it a parameter means the next reader cannot forget it.
   *
   * @param decisionId the identifier
   * @param tenantId the tenant
   * @param requestId the caller's idempotency key
   * @param recordedAt when the decision was written
   * @param response the decision
   * @param bundleHash the bundle that decided it, or empty if the row has none
   * @return the record, with the write-only fields defaulted
   */
  public static DecisionRecord readBack(
      String decisionId,
      String tenantId,
      String requestId,
      Instant recordedAt,
      DecisionResponse response,
      Optional<String> bundleHash) {
    return new DecisionRecord(
        decisionId,
        tenantId,
        requestId,
        Optional.empty(),
        recordedAt,
        recordedAt,
        0L,
        "UTC",
        0L,
        Optional.empty(),
        Optional.empty(),
        bundleHash,
        "unknown",
        response,
        "");
  }
}
